def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    my_d = me.count('D')

    if op_c == 0:
        return 'D'

    if op_d == 0:
        if my_d > 0:
            return 'D'
        return 'C'

    if op_d * 2 > n:
        return 'D'

    last_me = me[-1]
    last_op = op[-1]

    if n >= 95 and last_op == 'D':
        return 'D'

    if last_me == 'D' and last_op == 'C':
        return 'D'
    if last_me == 'D' and last_op == 'D':
        return 'C'
    if last_me == 'C' and last_op == 'D':
        return 'D'

    if n >= 95:
        return 'C'
    if my_d == 0:
        if rng.random() < 0.2:
            return 'D'
        return 'C'
    else:
        if rng.random() < 0.05:
            return 'D'
        return 'C'
